CREATE INDEX "worker_job_artifacts_scope_closure_gc_idx" ON "public"."worker_job_artifacts" USING "btree" ("gc_cleanup_state", "gc_claim_expires_at", "expires_at", "created_at", "id") WHERE (("artifact_role" IS NOT NULL) AND (("lifecycle_state" = ANY (ARRAY['ready'::"text", 'expired'::"text"])) OR (("lifecycle_state" = 'deleted'::"text") AND ("gc_cleanup_state" = 'pending'::"text"))));
